using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using Extensions.Pack;
using Microsoft.AspNetCore.Mvc;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Minimal API")]
    [TestClass]
    public class RJIT_CR_MAPI_00012 : MinimalApiTestBase
    {
        [TestMethod]
        public void Do_Not_Declare_Api_Versions_Which_Not_Exist()
        {
            // All api version mappings
            var hasVersionStatements = (from syntaxTree in ProductiveSyntaxTrees
                                        where syntaxTree.SyntaxTree.Contains(".HasApiVersion(")
                                        let matches = GlobalRegex.HasVersionRegex().Matches(syntaxTree.SyntaxTree)
                                        from match in matches
                                        where match.Success
                                        select new
                                        {
                                            Version = match.Groups[1].Value.ToInt(),
                                            FileName = syntaxTree.FileName,
                                            SyntaxTree = syntaxTree.SyntaxTree
                                        }).ToImmutableList();

            var versionWhichAreNotUsed = hasVersionStatements.Except(AllApiVersions, item => item.Version, item => item.MajorVersion).ToImmutableList();

            var codeSample = AllApiVersions.Select(v => $".HasApiVersion(new ApiVersion({v}))").Flatten($"{Environment.NewLine}                                  ");
            
            var invalidEndpointMappings = (from missingVersion in versionWhichAreNotUsed
                                           select new
                                           {
                                               Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Existing Versions:  {AllApiVersions.Select(item => item.ToString()).Flatten(";")}
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Registered Version: {missingVersion.Version}
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

 // Setup API versioning
var apiVersionSet = webApplication.NewApiVersionSet()
                                  {codeSample}
                                  .ReportApiVersions()
                                  .Build();
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                           }).ToImmutableList();

            Assert.IsTrue(invalidEndpointMappings.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MAPI_00012

Please do not register api versions which are not really used

Findings {invalidEndpointMappings.Count}': 

{invalidEndpointMappings.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
}
